package org.brightstats.desktop;

import java.util.*;
import javafx.application.Platform;
import javafx.scene.*;
import javafx.scene.chart.*;
import javafx.scene.control.*;
import javafx.scene.input.*;

/** Display-only exploration; chart data and numerical report arrays are never edited. */
final class ChartTools {
    private ChartTools(){}
    record AxisState(boolean automatic,double lower,double upper,double tick){}
    record HoverPoint(double x,double y,String text){}
    static void install(Node node){if(node instanceof XYChart<?,?> chart)installChart(chart);else if(node instanceof TabPane tabs)for(var tab:tabs.getTabs())install(tab.getContent());else if(node instanceof ScrollPane scroll)install(scroll.getContent());else if(node instanceof Parent parent)for(Node child:parent.getChildrenUnmodifiable())install(child);}
    static void installChart(XYChart<?,?> chart){if(chart.getProperties().containsKey("brightstats.chartTools"))return;State state=new State(chart);chart.getProperties().put("brightstats.chartTools",state);state.install();}
    @SuppressWarnings("unchecked") static Set<Integer> hidden(XYChart<?,?> chart){Object value=chart.getProperties().get("brightstats.hiddenSeries");return value instanceof Set<?>?(Set<Integer>)value:Set.of();}
    static String tsv(XYChart<?,?> chart){StringBuilder text=new StringBuilder("Series\tHidden\tX\tY\tPoint label\n");for(int j=0;j<chart.getData().size();j++){var series=chart.getData().get(j);for(var point:series.getData())text.append(cell(Objects.toString(series.getName(),"Series "+(j+1)),true)).append('\t').append(hidden(chart).contains(j)).append('\t').append(cell(Objects.toString(point.getXValue(),""),!(point.getXValue() instanceof Number))).append('\t').append(cell(Objects.toString(point.getYValue(),""),!(point.getYValue() instanceof Number))).append('\t').append(cell(Objects.toString(point.getExtraValue(),""),true)).append('\n');}return text.toString();}
    private static String cell(String value,boolean label){if(label&&!value.isEmpty()&&"=+-@".indexOf(value.charAt(0))>=0)value="'"+value;return value.chars().anyMatch(c->c=='\t'||c=='\n'||c=='\r'||c=='"')?'"'+value.replace("\"","\"\"")+'"':value;}
    static final class State {
        final XYChart<?,?> chart;final Set<Integer> hidden=new LinkedHashSet<>();final AxisState originalX,originalY;final Tooltip hover=new Tooltip();final ContextMenu menu=new ContextMenu();final Map<XYChart.Series<?,?>,Boolean> knownSeries=new WeakHashMap<>();final Map<XYChart.Data<?,?>,Boolean> knownPoints=new WeakHashMap<>();double startX,startY;AxisState dragX,dragY;boolean panning,updatePending;final Map<Long,List<HoverPoint>> hoverIndex=new HashMap<>();
        State(XYChart<?,?> chart){this.chart=chart;originalX=capture(chart.getXAxis());originalY=capture(chart.getYAxis());chart.getProperties().put("brightstats.hiddenSeries",hidden);}
        void install(){chart.setAnimated(false);chart.setFocusTraversable(true);if(!chart.accessibleHelpProperty().isBound())chart.setAccessibleHelp("Ctrl + wheel: zoom numeric axes. Alt + drag: pan. Ctrl + 0: reset. Right click for series visibility and plotted data.");MenuItem reset=new MenuItem("Reset chart view");reset.setOnAction(e->reset());MenuItem show=new MenuItem("Show all series");show.setOnAction(e->{hidden.clear();visibility();});MenuItem copy=new MenuItem("Copy plotted series data (TSV)");copy.setOnAction(e->{ClipboardContent content=new ClipboardContent();content.putString(tsv(chart));Clipboard.getSystemClipboard().setContent(content);});Menu series=new Menu("Series visibility");menu.getItems().setAll(reset,show,series,new SeparatorMenuItem(),copy);menu.setOnShowing(e->{series.getItems().clear();for(int j=0;j<chart.getData().size();j++){final int index=j;CheckMenuItem item=new CheckMenuItem(Objects.toString(chart.getData().get(j).getName(),"Series "+(j+1)));item.setSelected(!hidden.contains(j));item.setOnAction(event->toggle(index));series.getItems().add(item);}});chart.addEventHandler(ContextMenuEvent.CONTEXT_MENU_REQUESTED,e->{menu.show(chart,e.getScreenX(),e.getScreenY());e.consume();});Tooltip.install(chart,hover);
            chart.addEventFilter(ScrollEvent.SCROLL,e->{if(!e.isControlDown()||!inside(e.getSceneX(),e.getSceneY()))return;double factor=e.getDeltaY()>0?1/1.18:1.18;zoom(chart.getXAxis(),factor,axisValue(chart.getXAxis(),e.getSceneX(),e.getSceneY()));zoom(chart.getYAxis(),factor,axisValue(chart.getYAxis(),e.getSceneX(),e.getSceneY()));e.consume();});
            chart.addEventFilter(MouseEvent.MOUSE_PRESSED,e->{if(e.isAltDown()&&e.getButton()==MouseButton.PRIMARY&&inside(e.getSceneX(),e.getSceneY())){panning=true;startX=e.getSceneX();startY=e.getSceneY();dragX=capture(chart.getXAxis());dragY=capture(chart.getYAxis());e.consume();}});
            chart.addEventFilter(MouseEvent.MOUSE_DRAGGED,e->{if(panning){pan(chart.getXAxis(),dragX,-(e.getSceneX()-startX)/Math.max(1,chart.getXAxis().getWidth()));pan(chart.getYAxis(),dragY,(e.getSceneY()-startY)/Math.max(1,chart.getYAxis().getHeight()));e.consume();}});chart.addEventFilter(MouseEvent.MOUSE_RELEASED,e->{if(panning){panning=false;e.consume();}});chart.addEventHandler(KeyEvent.KEY_PRESSED,e->{if(e.isControlDown()&&e.getCode()==KeyCode.DIGIT0){reset();e.consume();}});chart.addEventHandler(MouseEvent.MOUSE_CLICKED,e->{if(inside(e.getSceneX(),e.getSceneY()))chart.requestFocus();});chart.addEventHandler(MouseEvent.MOUSE_MOVED,e->hover(e.getSceneX(),e.getSceneY()));chart.getData().addListener((javafx.collections.ListChangeListener)change->sync());chart.needsLayoutProperty().addListener((o,a,b)->{if(!b){legend();rebuildHover();}});chart.sceneProperty().addListener((o,a,b)->{if(b!=null)Platform.runLater(this::legend);});sync();Platform.runLater(this::legend);
        }
        void reset(){restore(chart.getXAxis(),originalX);restore(chart.getYAxis(),originalY);}
        void toggle(int index){if(index<0||index>=chart.getData().size())return;if(!hidden.add(index))hidden.remove(index);visibility();}
        void sync(){hidden.removeIf(i->i>=chart.getData().size());for(var series:chart.getData()){if(knownSeries.put(series,true)==null){series.nodeProperty().addListener((o,a,b)->scheduleUpdate());series.getData().addListener((javafx.collections.ListChangeListener)change->sync());}for(var point:series.getData())if(knownPoints.put(point,true)==null)point.nodeProperty().addListener((o,a,b)->{link(point,b);scheduleUpdate();});}visibility();Platform.runLater(this::legend);}
        void visibility(){for(int j=0;j<chart.getData().size();j++){var series=chart.getData().get(j);visible(series.getNode(),!hidden.contains(j));for(var point:series.getData()){visible(point.getNode(),!hidden.contains(j));link(point,point.getNode());}}if(chart instanceof UncertaintyChart uncertainty)uncertainty.visibilityChanged();legend();rebuildHover();}
        void link(XYChart.Data<?,?> point,Node node){if(node==null||node.getProperties().putIfAbsent("brightstats.sourceLink",true)!=null)return;node.addEventHandler(MouseEvent.MOUSE_CLICKED,e->{if(point.getExtraValue() instanceof org.brightstats.report.GraphicPoint source)VisualSelection.publish(node,source);});node.addEventHandler(KeyEvent.KEY_PRESSED,e->{if((e.getCode()==KeyCode.ENTER||e.getCode()==KeyCode.SPACE)&&point.getExtraValue() instanceof org.brightstats.report.GraphicPoint source){VisualSelection.publish(node,source);e.consume();}});if(point.getExtraValue() instanceof org.brightstats.report.GraphicPoint){node.setFocusTraversable(true);if(!node.accessibleHelpProperty().isBound())node.setAccessibleHelp("Select this plotted mark to link its recorded source rows or columns.");}}
        void scheduleUpdate(){if(updatePending)return;updatePending=true;Platform.runLater(()->{updatePending=false;visibility();});}
        private static void visible(Node node,boolean show){if(node==null)return;node.getProperties().putIfAbsent("brightstats.originalVisibility",node.isVisible());boolean original=Boolean.TRUE.equals(node.getProperties().get("brightstats.originalVisibility"));if(!node.visibleProperty().isBound())node.setVisible(show&&original);}
        void legend(){Map<String,List<Integer>> indices=new HashMap<>();for(int j=0;j<chart.getData().size();j++)indices.computeIfAbsent(Objects.toString(chart.getData().get(j).getName(),""),k->new ArrayList<>()).add(j);for(Node node:chart.lookupAll(".chart-legend-item"))if(node instanceof Label label){var matches=indices.get(label.getText());if(matches==null||matches.size()!=1)continue;int index=matches.getFirst();label.setOpacity(hidden.contains(index)?.4:1);label.setCursor(javafx.scene.Cursor.HAND);label.setOnMouseClicked(e->{toggle(index);e.consume();});label.setFocusTraversable(true);label.setOnKeyPressed(e->{if(e.getCode()==KeyCode.SPACE||e.getCode()==KeyCode.ENTER){toggle(index);e.consume();}});if(!label.accessibleHelpProperty().isBound())label.setAccessibleHelp("Toggle visibility of series "+label.getText()+". Data and analysis do not change.");}}
        boolean inside(double sceneX,double sceneY){Node plot=chart.lookup(".chart-plot-background");return plot!=null&&plot.localToScene(plot.getBoundsInLocal()).contains(sceneX,sceneY);}
        void rebuildHover(){hoverIndex.clear();if(chart.getScene()==null)return;Node plot=chart.lookup(".chart-plot-background");if(plot==null)return;var bounds=chart.sceneToLocal(plot.localToScene(plot.getBoundsInLocal()));for(int index=0;index<chart.getData().size();index++){if(hidden.contains(index))continue;var series=chart.getData().get(index);for(var point:series.getData()){double x=display(chart.getXAxis(),point.getXValue()),y=display(chart.getYAxis(),point.getYValue());if(!Double.isFinite(x)||!Double.isFinite(y))continue;var px=chart.sceneToLocal(chart.getXAxis().localToScene(x,0));var py=chart.sceneToLocal(chart.getYAxis().localToScene(0,y));x=px.getX();y=py.getY();if(!bounds.contains(x,y))continue;String text=Objects.toString(series.getName(),"Series "+(index+1))+"\n"+Objects.toString(point.getExtraValue(),"")+"\nX: "+point.getXValue()+"\nY: "+point.getYValue();hoverIndex.computeIfAbsent(bucket((int)Math.floor(x/40),(int)Math.floor(y/40)),k->new ArrayList<>()).add(new HoverPoint(x,y,text));}}}
        void hover(double sceneX,double sceneY){if(!inside(sceneX,sceneY))return;var local=chart.sceneToLocal(sceneX,sceneY);int cellX=(int)Math.floor(local.getX()/40),cellY=(int)Math.floor(local.getY()/40);double best=24*24;String text="Ctrl + wheel: zoom · Alt + drag: pan · Ctrl + 0: reset";for(int x=cellX-1;x<=cellX+1;x++)for(int y=cellY-1;y<=cellY+1;y++)for(var point:hoverIndex.getOrDefault(bucket(x,y),List.of())){double distance=Math.pow(point.x()-local.getX(),2)+Math.pow(point.y()-local.getY(),2);if(distance<best){best=distance;text=point.text();}}hover.setText(text);}
        private static long bucket(int x,int y){return ((long)x<<32)^(y&0xffffffffL);}

    }
    static AxisState capture(Axis<?> axis){return axis instanceof NumberAxis number?new AxisState(number.isAutoRanging(),number.getLowerBound(),number.getUpperBound(),number.getTickUnit()):null;}
    static void restore(Axis<?> axis,AxisState state){if(state==null||!(axis instanceof NumberAxis number))return;if(state.automatic())number.setAutoRanging(true);else{number.setAutoRanging(false);number.setLowerBound(state.lower());number.setUpperBound(state.upper());number.setTickUnit(state.tick());}}
    static void zoom(Axis<?> axis,double factor,double center){if(!(axis instanceof NumberAxis number)||!Double.isFinite(center))return;double low=center+(number.getLowerBound()-center)*factor,high=center+(number.getUpperBound()-center)*factor;bounds(number,low,high);}
    static void pan(Axis<?> axis,AxisState state,double fraction){if(!(axis instanceof NumberAxis number)||state==null)return;double shift=(state.upper()-state.lower())*fraction;bounds(number,state.lower()+shift,state.upper()+shift);}
    private static void bounds(NumberAxis axis,double low,double high){double span=high-low,scale=Math.max(Math.abs(low),Math.abs(high));if(!Double.isFinite(low)||!Double.isFinite(high)||!Double.isFinite(span)||span<=Math.max(Double.MIN_NORMAL,32*Math.ulp(scale)))return;axis.setAutoRanging(false);axis.setLowerBound(low);axis.setUpperBound(high);double desired=span/6,power=Math.pow(10,Math.floor(Math.log10(desired))),normalized=desired/power,tick=power*(normalized<=1?1:normalized<=2?2:normalized<=5?5:10);if(Double.isFinite(tick)&&tick>0)axis.setTickUnit(tick);}
    private static double axisValue(Axis<?> axis,double x,double y){if(!(axis instanceof NumberAxis number))return Double.NaN;var point=axis.sceneToLocal(x,y);Number value=number.getValueForDisplay(number.getSide().isHorizontal()?point.getX():point.getY());return value==null?Double.NaN:value.doubleValue();}
    @SuppressWarnings({"rawtypes","unchecked"}) private static double display(Axis axis,Object value){try{return axis.getDisplayPosition(value);}catch(RuntimeException invalid){return Double.NaN;}}
}
